{"explanation":"Think of x² + 6x as the area of a square with side x plus two rectangles of size x by 3 (the 6x split in half). Put them together and you get an L-shape with a missing corner. That corner is a 3 by 3 square with area 9. Adding it completes the big square of side (x+3), so x² + 6x + 9 = (x+3)², and therefore x² + 6x = (x+3)² − 9. Drag the slider to change x and see the pieces resize.","manimCode":"const u = 0.6; // units per 1 of math length
let x = 3;
let group = null;
let info = null;

const title = new Text({ text: 'Completing the square: x² + 6x', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.5, 0]);
scene.add(title);

const eq = new MathTex({ latex: 'x^2+6x+9=(x+3)^2', color: YELLOW });
await eq.waitForRender();
eq.moveTo([0, -3.4, 0]);
scene.add(eq);

const eq2 = new MathTex({ latex: 'x^2+6x=(x+3)^2-9', color: GREEN });
await eq2.waitForRender();
eq2.moveTo([4.5, 0, 0]);
scene.add(eq2);

function rect(x0, y0, w, h, color, op) {
  // x0,y0 = top-left in world coordinates
  const r = new Polygon({
    vertices: [[x0, y0, 0], [x0 + w, y0, 0], [x0 + w, y0 - h, 0], [x0, y0 - h, 0]],
    color: color
  });
  r.setFill(color, op);
  return r;
}

function build() {
  if (group) scene.remove(group);
  if (info) scene.remove(info);
  const s = x * u;
  const t = 3 * u;
  const total = s + 2 * t;
  const left = -2.5 - total / 2 + 0.0;
  const top = 0.3 + total / 2;
  const sq = rect(left, top, s, s, BLUE, 0.5);
  const r1 = rect(left + s, top, t, s, ORANGE, 0.5);
  const r2 = rect(left, top - s, s, t, ORANGE, 0.5);
  const corner = rect(left + s, top - s, t, t, RED, 0.25);
  // corner is the "missing" piece: only partial 3x3 → use 3 wide
  group = new VGroup(sq, r1, r2, corner);
  scene.add(group);
  info = new Text({ text: 'x = ' + x.toFixed(1) + '   blue: x²   orange: 3x + 3x   red: 9', color: WHITE, fontSize: 22 });
  info.moveTo([-2.5, -3.0, 0]);
  scene.add(info);
}
// Adjust: side of full square = x + 3 (rectangles are 3 wide each, but only one corner of 3x3)
function build2() {
  if (group) scene.remove(group);
  if (info) scene.remove(info);
  const s = x * u;
  const t = 3 * u;
  const total = s + t;
  const left = -2.5 - total / 2;
  const top = 0.1 + total / 2;
  const sq = rect(left, top, s, s, BLUE, 0.5);
  const r1 = rect(left + s, top, t, s, ORANGE, 0.5);
  const r2 = rect(left, top - s, s, t, ORANGE, 0.5);
  const corner = rect(left + s, top - s, t, t, RED, 0.35);
  group = new VGroup(sq, r1, r2, corner);
  scene.add(group);
  info = new Text({ text: 'x = ' + x.toFixed(1) + '  |  blue: x²  orange: 3x + 3x  red: 3² = 9', color: WHITE, fontSize: 20 });
  info.moveTo([-2.5, -3.0, 0]);
  scene.add(info);
}
build2();

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'x', min: 0.5, max: 5, value: 3, step: 0.1, onChange: (v) => { x = v; build2(); } });

await scene.wait(999999);"}

